(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-l3"] = {"id":"x01-l3","patterns":["L3-science","PARA-opinion"],"title":{"en":"Listening Part 3: planning a seminar","tr":"Listening Part 3: bir seminer planlamak","fa":"Listening Part 3: برنامه‌ریزی یک سمینار"},"objective":{"en":"In this lesson you will learn to follow two students as they discuss their study, and to choose the ideas and opinions they finally agree on.","tr":"Bu derste derslerini konuşan iki öğrenciyi takip etmeyi ve sonunda üzerinde anlaştıkları fikirleri ve görüşleri seçmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را درباره‌ی درسشان دنبال کنی و ایده‌ها و نظرهایی را انتخاب کنی که آخر سر رویش توافق می‌کنند."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: planning a seminar","tr":"Listening Part 3: bir seminer planlamak","fa":"Listening Part 3: برنامه‌ریزی یک سمینار"},"objective":{"en":"In this lesson you will learn to follow two students as they discuss their study, and to choose the ideas and opinions they finally agree on.","tr":"Bu derste derslerini konuşan iki öğrenciyi takip etmeyi ve sonunda üzerinde anlaştıkları fikirleri ve görüşleri seçmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را درباره‌ی درسشان دنبال کنی و ایده‌ها و نظرهایی را انتخاب کنی که آخر سر رویش توافق می‌کنند."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Options in the box","tr":"Kutudaki seçenek","fa":"گزینه‌های کادر"},"value":"A-H"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a seminar on coral reefs","tr":"Bu sınav: mercan resifleri üzerine bir seminer","fa":"این آزمون: سمیناری درباره‌ی صخره‌های مرجانی"},"intro":{"en":"Part 3 is always about study: students, sometimes with a tutor, talk about a lecture, a project or an assignment. About half the topics are science and the environment, as here.","tr":"Part 3 her zaman ders çalışmayla ilgilidir: öğrenciler, bazen bir öğretim görevlisiyle, bir ders, proje ya da ödev hakkında konuşur. Konuların yaklaşık yarısı burada olduğu gibi bilim ve çevredir.","fa":"Part 3 همیشه درباره‌ی درس است: دانشجوها، گاهی با استاد راهنما، درباره‌ی یک کلاس، پروژه یا تکلیف حرف می‌زنند. حدود نصف موضوع‌ها مثل این‌جا علم و محیط زیست‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-l3-ctx","exam":true,"patterns":["L3-science","PARA-opinion"],"often":{"pattern":"L3-science","n":19,"of":40,"label":{"en":"Comes up often in the real exam: 19 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 19’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Two students plan a seminar","tr":"İki öğrenci bir semineri planlıyor","fa":"دو دانشجو یک سمینار را برنامه‌ریزی می‌کنند"},"asks":{"en":"After a lecture, two students say what surprised them, choose what to put in their presentation and give their opinion of each reading resource on their list.","tr":"Bir dersten sonra iki öğrenci neyin onları şaşırttığını söylüyor, sunumlarına ne koyacaklarını seçiyor ve listelerindeki her kaynak hakkında görüş bildiriyor.","fa":"بعد از یک کلاس، دو دانشجو می‌گویند چه چیزی برایشان عجیب بود، انتخاب می‌کنند چه چیزی را در ارائه بیاورند و درباره‌ی هر منبع فهرستشان نظر می‌دهند."},"fields":["What surprised them","What to include","Resources: textbook, slides, database, documentary, article, website"],"words":[{"a":"surprised","b":"I never knew / that was a shock / I didn’t expect","tr":"şaşırmak","fa":"تعجب کردن"},{"a":"already known","b":"I knew that already / nothing new","tr":"zaten biliniyor","fa":"از قبل معلوم"},{"a":"include","b":"put in / let’s use / that would work","tr":"dahil etmek","fa":"گنجاندن"},{"a":"leave out","b":"let’s drop it / we don’t need that","tr":"çıkarmak","fa":"کنار گذاشتن"},{"a":"up to date","b":"the latest figures / just been revised","tr":"güncel","fa":"به‌روز"},{"a":"easy to search","b":"you find things in no time","tr":"aranması kolay","fa":"جستجوی آسان"},{"a":"too technical","b":"full of jargon / written for experts","tr":"fazla teknik","fa":"خیلی تخصصی"},{"a":"only one region","b":"it only looks at one country","tr":"tek bir bölge","fa":"فقط یک منطقه"},{"a":"agree","b":"fair point / exactly / yes, let’s","tr":"katılmak","fa":"موافق بودن"},{"a":"disagree","b":"I’m not sure... / I doubt it","tr":"katılmamak","fa":"مخالف بودن"},{"a":"images","b":"great photos / good visuals","tr":"görseller","fa":"تصویرها"}],"traps":[{"en":"A choice is suggested and then dropped: \"Why don’t we show a short film?\" ... \"It’s far too long.\" Only an idea both students accept counts.","tr":"Bir seçenek önerilip bırakılır: \"Kısa bir film göstersek mi?\" ... \"Çok uzun.\" Yalnızca iki öğrencinin de kabul ettiği fikir sayılır.","fa":"یک پیشنهاد مطرح و بعد کنار گذاشته می‌شود: «یک فیلم کوتاه نشان بدهیم؟» ... «خیلی طولانی است». فقط ایده‌ای حساب است که هر دو قبولش کنند."},{"en":"In the box of eight, two opinions are never used, and some are said and then denied (\"It isn’t expensive, but...\"). Match the opinion the students settle on.","tr":"Sekizli kutuda iki görüş hiç kullanılmaz, bazıları da söylenip reddedilir (\"Pahalı değil, ama...\"). Öğrencilerin vardığı görüşü eşleştir.","fa":"در کادر هشت‌تایی دو نظر اصلاً استفاده نمی‌شوند و بعضی گفته و بعد رد می‌شوند («گران نیست، اما...»). نظری را جور کن که دانشجوها آخر سر رویش توافق می‌کنند."},{"en":"Choose TWO: three wrong options are mentioned too, often as \"I knew that already\" or \"I’d expected that\".","tr":"İki seçim: üç yanlış seçenekten de söz edilir, çoğu zaman \"Bunu zaten biliyordum\" ya da \"Bunu bekliyordum\" diye.","fa":"دو گزینه: از سه گزینه‌ی غلط هم حرف زده می‌شود، اغلب با «این را از قبل می‌دانستم» یا «انتظارش را داشتم»."}],"example":{"lines":[["Student A","The interviews were the most useful part, weren’t they?"],["Student B","I’m not convinced. They were interesting, but the survey gave us the numbers we actually used."],["Student A","Fair point. The survey, then."]],"item":"Which part of the project did the students find most useful? A the interviews  B the survey  C the reading list","answer":"B","why":{"en":"A is suggested, then B wins: \"Fair point. The survey, then.\"","tr":"A öneriliyor, sonra B kazanıyor: \"Haklısın. O zaman anket.\"","fa":"اول A پیشنهاد می‌شود، بعد B برنده می‌شود: «حرف درستی است. پس نظرسنجی»."}}},{"id":"L3-science","ctx":["L3-science"],"title":{"en":"Nature, environment and experiments","tr":"Doğa, çevre ve deneyler","fa":"طبیعت، محیط زیست و آزمایش"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on an experiment, an animal or plant, the sea, a volcano or recycling. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, bir deney, bir hayvan ya da bitki, deniz, bir yanardağ ya da geri dönüşüm üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی یک آزمایش، یک حیوان یا گیاه، دریا، یک آتشفشان یا بازیافت را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What was the aim of the experiment?","What went wrong with the first method?","What do they decide to change?","Which TWO findings surprised them?","Complete the flow-chart of the procedure."],"words":[{"a":"experiment","b":"the test we ran","tr":"deney","fa":"آزمایش"},{"a":"hypothesis","b":"what we expected to find","tr":"hipotez","fa":"فرضیه"},{"a":"sample","b":"the seeds we tested / the group","tr":"örneklem","fa":"نمونه"},{"a":"variable","b":"the thing we changed","tr":"değişken","fa":"متغیر"},{"a":"results","b":"what we found","tr":"sonuçlar","fa":"نتیجه‌ها"},{"a":"unexpected","b":"we didn't predict that","tr":"beklenmedik","fa":"غیرمنتظره"},{"a":"reliable","b":"we can trust it","tr":"güvenilir","fa":"قابل اعتماد"},{"a":"measure","b":"record how much or how tall","tr":"ölçmek","fa":"اندازه گرفتن"},{"a":"species","b":"kinds of animal or plant","tr":"tür","fa":"گونه"},{"a":"extinct","b":"died out / no longer exists","tr":"soyu tükenmiş","fa":"منقرض"},{"a":"sustainable","b":"doesn't harm the planet","tr":"sürdürülebilir","fa":"پایدار"},{"a":"recycle","b":"use the material again","tr":"geri dönüştürmek","fa":"بازیافت کردن"},{"a":"procedure","b":"the steps we followed","tr":"işlem sırası","fa":"روش کار"}],"traps":[{"en":"Flow-charts: steps are not always said in time order (\"before that, we soaked them\"). Put them in the order they happened.","tr":"Akış şemaları: adımlar her zaman zaman sırasıyla söylenmez (\"ondan önce onları ıslattık\"). Onları olduğu sıraya koy.","fa":"فلوچارت‌ها: مرحله‌ها همیشه به ترتیب زمانی گفته نمی‌شوند («قبلش خیسشان کردیم»). به ترتیبی که اتفاق افتادند بچینشان."},{"en":"Result against expectation: \"we thought light would matter most, but actually temperature did\".","tr":"Beklentiye karşı sonuç: \"ışığın en önemli olduğunu sanıyorduk ama aslında sıcaklıkmış\".","fa":"نتیجه در برابر انتظار: «فکر می‌کردیم نور از همه مهم‌تر است، ولی در واقع دما بود»."}],"example":{"lines":[["Tutor","What affected germination most?"],["Student","We expected light to make the biggest difference."],["Student","But in fact the seeds we kept warm grew fastest, whatever the light."]],"item":"Which factor had the greatest effect?  A light   B temperature   C water","answer":"B","why":{"en":"Light was the expectation. \"In fact\" introduces the result: the warm seeds grew fastest, so temperature.","tr":"Işık beklentiydi. \"In fact\" sonucu getiriyor: sıcak tutulan tohumlar en hızlı büyüdü, yani sıcaklık.","fa":"نور انتظارشان بود. «In fact» نتیجه را می‌آورد: دانه‌های گرم سریع‌تر رشد کردند، پس دما."}},"general":true,"patterns":["L3-science"],"often":{"pattern":"L3-science","n":19,"of":40,"label":{"en":"Comes up often in the real exam: 19 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 19’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Two pairs, then a box of eight","tr":"İki çift, sonra sekizli bir kutu","fa":"دو جفت سؤال، بعد یک کادر هشت‌تایی"},"body":{"en":"Questions 21-22 and 23-24: choose TWO letters from A-E for each pair; each correct letter is one mark, in any order. Questions 25-30: six resources, a box of eight opinions, A-H. Each letter is used once and two are left over.","tr":"Soru 21-22 ve 23-24: her çift için A-E’den İKİ harf seç; her doğru harf bir puan, sıra önemli değil. Soru 25-30: altı kaynak, A-H arasında sekiz görüşlük bir kutu. Her harf bir kez kullanılır, ikisi artar.","fa":"سؤال‌های ۲۱-۲۲ و ۲۳-۲۴: برای هر جفت دو حرف از A تا E انتخاب کن؛ هر حرف درست یک نمره دارد و ترتیبش مهم نیست. سؤال‌های ۲۵ تا ۳۰: شش منبع و یک کادر هشت‌تایی از نظرها (A تا H). هر حرف یک بار می‌آید و دو تا اضافه می‌مانند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Before you listen, turn each option into a short idea in your head: B = \"many species have no name\".","tr":"Dinlemeden önce her seçeneği kafanda kısa bir fikre çevir: B = \"birçok türün adı yok\".","fa":"قبل از گوش دادن، هر گزینه را در ذهنت به یک ایده‌ی کوتاه تبدیل کن: B یعنی «خیلی از گونه‌ها اسم ندارند»."},{"en":"Follow both voices. One student suggests; the answer is what the other accepts.","tr":"İki sesi de takip et. Bir öğrenci önerir; cevap diğerinin kabul ettiği şeydir.","fa":"هر دو صدا را دنبال کن. یک دانشجو پیشنهاد می‌دهد؛ جواب چیزی است که دیگری قبول می‌کند."},{"en":"Tick an option only after the exchange ends: fair point, exactly, let’s do that.","tr":"Bir seçeneği ancak konuşma bitince işaretle: fair point, exactly, let’s do that.","fa":"فقط وقتی بحث تمام شد گزینه را علامت بزن: fair point، exactly، let’s do that."},{"en":"For the box, hear the resource name first, then wait for the final opinion about it.","tr":"Kutu için önce kaynağın adını duy, sonra onunla ilgili son görüşü bekle.","fa":"برای کادر، اول اسم منبع را بشنو، بعد منتظر نظر نهایی درباره‌اش بمان."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"How students agree and disagree","tr":"Öğrenciler nasıl katılır ve karşı çıkar","fa":"دانشجوها چطور موافقت و مخالفت می‌کنند"},"table":{"headers":{"en":["Agree (keep it)","Disagree (drop it)"],"tr":["Katılıyor (kalsın)","Katılmıyor (çıksın)"],"fa":["موافق (بماند)","مخالف (حذف شود)"]},"rows":[["Fair point. / Exactly.","I’m not sure we’re allowed..."],["Yes, let’s do that.","That would take ages."],["That would work well.","I’d forget the..."],["Agreed.","Let’s leave it, then."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One pair, step by step","tr":"Bir çift, adım adım","fa":"یک جفت، قدم به قدم"},"instruction":"Choose TWO letters, A-E.","item":"Which TWO problems did the students have? A not enough time  B a broken camera  C a small sample  D a late tutor  E lost notes","lines":[["Student A","We never had enough time, did we?"],["Student B","I don’t think time was the problem. Only twelve people answered, and the camera stopped working on the second day."],["Student A","True. Those two hurt us most."]],"answer":"B, C","walk":[{"en":"A is suggested first, but Student B rejects it.","tr":"A önce öneriliyor ama B öğrencisi reddediyor.","fa":"اول A پیشنهاد می‌شود، اما دانشجوی B ردش می‌کند."},{"en":"\"Only twelve people answered\" = a small sample (C). \"The camera stopped working\" = broken camera (B).","tr":"\"Yalnızca on iki kişi cevap verdi\" = küçük örneklem (C). \"Kamera çalışmayı bıraktı\" = bozuk kamera (B).","fa":"«فقط دوازده نفر جواب دادند» یعنی نمونه‌ی کوچک (C). «دوربین از کار افتاد» یعنی دوربین خراب (B)."},{"en":"Student A agrees: \"Those two\". Write B and C, in any order.","tr":"A öğrencisi katılıyor: \"Bu ikisi\". B ve C yaz, sıra fark etmez.","fa":"دانشجوی A موافقت می‌کند: «همین دو تا». B و C را بنویس، ترتیبش مهم نیست."}]},"quick":{"prompt":"\"Shall we use the old survey?\" \"I’d rather not. It’s from 2015.\" \"Fine, we’ll do our own.\" What do they decide?","options":["carry out a new survey","use the old survey","use no survey"],"correct":0,"why":{"en":"The old survey is rejected; they agree to \"do our own\".","tr":"Eski anket reddediliyor; \"kendimizinkini yapalım\" diye anlaşıyorlar.","fa":"نظرسنجی قدیمی رد می‌شود؛ توافق می‌کنند «خودمان یکی انجام دهیم»."}},"remember":{"en":"In Part 3, the answer is what both students accept at the end of the exchange.","tr":"Part 3’te cevap, konuşmanın sonunda iki öğrencinin de kabul ettiği şeydir.","fa":"در Part 3 جواب چیزی است که هر دو دانشجو در آخر بحث قبولش می‌کنند."},"type":"explain","id":"c-x01-l3-e","course":"ielts-exams","exam":"exam-01","unit":"x01-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"A seminar on coral reefs","tr":"Mercan resifleri üzerine bir seminer","fa":"سمیناری درباره‌ی صخره‌های مرجانی"},"timed":7,"ctx":["L3-science"],"script":[{"who":"Owen","line":"Hi Nadia. Have you got a minute to talk about the seminar? We need to decide what we're presenting."},{"who":"Nadia","line":"Sure. Did you think the lecture on coral reefs was useful?"},{"who":"Owen","line":"Very. I knew reefs were rich in life, but I had no idea how much of it hasn't even been described yet. She said scientists may have named only a quarter of the species that live on reefs."},{"who":"Nadia","line":"That amazed me too. And the other thing I wasn't expecting was the size. They hold about a quarter of all marine species, but they cover less than one per cent of the sea floor."},{"who":"Owen","line":"Yes, that's a striking contrast. What about the part on cleaner fish? Some people near me were very excited about it."},{"who":"Nadia","line":"I'd read about cleaner fish at school, so that wasn't new for me. And I thought she'd say that reefs recover quickly after storms, but she said the opposite: it can take decades."},{"who":"Owen","line":"She also said that tourism pays for a lot of reef protection. I'd expected that, to be honest; most marine parks charge divers an entry fee."},{"who":"Nadia","line":"Me too. It's the same where my family goes on holiday."},{"who":"Owen","line":"Right. OK, so for the presentation, what should we put in? I'd really like to compare reefs with rainforests. It's a comparison everybody understands."},{"who":"Nadia","line":"Agreed, that would work well at the start. I was also thinking of showing the video of the reef survey from the lecture."},{"who":"Owen","line":"I'm not sure we're allowed to use her video. And it's twelve minutes long; we only have fifteen in total."},{"who":"Nadia","line":"Fair point. We could interview some divers from the university club instead."},{"who":"Owen","line":"That would take ages to organise, and the seminar is next Thursday. What about a map showing which reefs are protected? That makes the point about how little is covered."},{"who":"Nadia","line":"Yes, let's do that. I'll find one. And I'd forget the temperature chart; the lecturer showed one already."},{"who":"Owen","line":"OK. So, the comparison with rainforests, and the map of protected areas."},{"who":"Nadia","line":"Now, the tutor gave us a list of resources. Shall we go through them and decide which ones to use?"},{"who":"Owen","line":"Good idea. First, the chapter in the textbook."},{"who":"Nadia","line":"I read it last night. It's clearly written, and it isn't out of date, but it's really an introduction. Everything in it was in the lecture, and more besides. It's too basic for a seminar."},{"who":"Owen","line":"Maybe we could just mention it in the handout as background reading for anyone who's interested."},{"who":"Nadia","line":"That's a good idea. But we shouldn't spend time on it in the talk itself."},{"who":"Owen","line":"Then the lecturer's slides. I thought they'd just repeat the textbook."},{"who":"Nadia","line":"Not at all. She updated them this term, so they have this year's survey results. No other source we've got has figures that new."},{"who":"Owen","line":"Great. What about the online species database?"},{"who":"Nadia","line":"I was worried it would be complicated, but it's actually very simple. You type a reef name and get a full list in seconds. Finding what you need takes no time."},{"who":"Owen","line":"Good. Then there's the documentary the tutor mentioned. It's a few years old now."},{"who":"Nadia","line":"It is, so I wouldn't use its numbers. But the underwater filming is beautiful. If we want pictures for our slides, that's the place to go."},{"who":"Owen","line":"And the journal article on reef fish. I tried to read it on the bus."},{"who":"Nadia","line":"How did you get on?"},{"who":"Owen","line":"Badly. It's full of statistics and specialist terms. I needed the library login to download it, but that was easy; the problem was understanding it. I think it's aimed at researchers, not students in their first year."},{"who":"Nadia","line":"Let's leave it, then. And the last one, the museum website?"},{"who":"Owen","line":"It looks good, but when I checked, all the information is about reefs in the Caribbean. There's nothing on the Pacific or the Indian Ocean."},{"who":"Nadia","line":"So it's fine if we want an example, but it won't give us the global picture."},{"who":"Owen","line":"Exactly. Shall we meet on Monday to put the slides together?"},{"who":"Nadia","line":"Monday's fine. Let's say two o'clock in the library."}],"groups":[{"instruction":"Questions 21-22. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":21,"n2":22,"kind":"mcq2","prompt":"Which TWO facts from the lecture surprised the students?","options":["A how quickly reefs recover after storms","B how many reef species have not been named","C how small an area reefs cover","D how fish keep coral clean","E how much tourism pays for reef protection"],"correct":[1,2],"evidence":"I had no idea how much of it hasn't even been described yet","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"B \"I had no idea how much... hasn’t been described\" and C \"I wasn’t expecting... less than one per cent\". Cleaner fish and tourism were not new to them, and reefs do not recover quickly.","tr":"B \"...ne kadarının tanımlanmadığını bilmiyordum\" ve C \"...yüzde birden az olduğunu beklemiyordum\". Temizlikçi balıklar ve turizm onlar için yeni değildi, resifler de hızlı toparlanmıyor.","fa":"B «نمی‌دانستم چقدرش هنوز توصیف نشده» و C «انتظار نداشتم... کمتر از یک درصد». ماهی‌های پاک‌کننده و گردشگری برایشان تازه نبود و صخره‌ها هم سریع ترمیم نمی‌شوند."}}]},{"instruction":"Questions 23-24. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":23,"n2":24,"kind":"mcq2","prompt":"Which TWO things will the students include in their presentation?","options":["A a video of a reef survey","B a comparison with rainforests","C interviews with divers","D a map of protected reefs","E a chart of sea temperatures"],"correct":[1,3],"evidence":"the comparison with rainforests, and the map of protected areas","trap":["TR-ruledout"],"why":{"en":"Both agree to B and D, and Owen sums them up. The video may not be allowed, the interviews would take too long, and the lecturer already showed a temperature chart.","tr":"İkisi de B ve D’de anlaşıyor, Owen özetliyor. Videoya izin olmayabilir, röportajlar çok uzun sürer, sıcaklık grafiğini de hoca zaten gösterdi.","fa":"هر دو روی B و D توافق می‌کنند و اوون جمع‌بندی می‌کند. شاید ویدیو مجاز نباشد، مصاحبه‌ها خیلی طول می‌کشند و نمودار دما را استاد قبلاً نشان داده."}}]},{"instruction":"Questions 25-30. What do the students think about each of the following resources? Choose SIX answers from the box and write the correct letter, A-H, next to Questions 25-30.","qtype":"matching","bank":["A It is too technical.","B It is out of date.","C It is a good source of images.","D It only covers one region.","E It is easy to search.","F It is too basic.","G It has the most recent figures.","H It is difficult to access."],"questions":[{"n":25,"kind":"match","prompt":"the textbook chapter","correct":5,"evidence":"It's too basic for a seminar","why":{"en":"\"It isn’t out of date\" rules out B. \"It’s really an introduction... too basic.\"","tr":"\"Eski değil\" B’yi eler. \"Aslında bir giriş... fazla temel.\"","fa":"«قدیمی نیست» B را رد می‌کند. «در واقع یک مقدمه است... خیلی مقدماتی»."},"trap":["TR-ruledout"]},{"n":26,"kind":"match","prompt":"the lecturer’s slides","correct":6,"evidence":"they have this year's survey results","why":{"en":"Updated this term with this year’s results: \"No other source... has figures that new.\"","tr":"Bu dönem güncellendi, bu yılın sonuçları var: \"Başka hiçbir kaynakta bu kadar yeni rakam yok.\"","fa":"این ترم به‌روز شده و نتیجه‌های امسال را دارد: «هیچ منبع دیگری عددهایی به این تازگی ندارد»."},"trap":["TR-paraphrase"]},{"n":27,"kind":"match","prompt":"the online species database","correct":4,"evidence":"Finding what you need takes no time","why":{"en":"Not complicated: \"type a reef name and get a full list in seconds\" = easy to search.","tr":"Karmaşık değil: \"bir resif adı yaz, saniyeler içinde tam liste gelsin\" = aranması kolay.","fa":"پیچیده نیست: «اسم صخره را تایپ کن و در چند ثانیه فهرست کامل را بگیر» یعنی جستجوی آسان."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":28,"kind":"match","prompt":"the documentary","correct":2,"evidence":"If we want pictures for our slides","why":{"en":"Its numbers are old (B is tempting), but the answer is about the filming: \"pictures for our slides\".","tr":"Rakamları eski (B çekici), ama cevap çekimle ilgili: \"slaytlarımız için resimler\".","fa":"عددهایش قدیمی‌اند (B وسوسه‌انگیز است)، اما جواب درباره‌ی فیلم‌برداری است: «تصویر برای اسلایدهایمان»."},"trap":["TR-ruledout"]},{"n":29,"kind":"match","prompt":"the journal article","correct":0,"evidence":"full of statistics and specialist terms","why":{"en":"Access was easy (H is ruled out); \"the problem was understanding it\": too technical.","tr":"Erişim kolaydı (H elenir); \"sorun onu anlamaktı\": fazla teknik.","fa":"دسترسی آسان بود (H رد می‌شود)؛ «مشکل فهمیدنش بود»: خیلی تخصصی."},"trap":["TR-ruledout"]},{"n":30,"kind":"match","prompt":"the museum website","correct":3,"evidence":"all the information is about reefs in the Caribbean","why":{"en":"\"All the information is about reefs in the Caribbean\": only one region.","tr":"\"Tüm bilgiler Karayipler’deki resifler hakkında\": tek bir bölge.","fa":"«همه‌ی اطلاعات درباره‌ی صخره‌های دریای کارائیب است»: فقط یک منطقه."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Nadia":{"accent":"Scottish","gender":"F","tts":{"engine":"piper","voice":"en_GB-alba-medium"},"role":"Student"},"Owen":{"accent":"Northern English","gender":"M","tts":{"engine":"piper","voice":"en_GB-northern_english_male-medium"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two students, Nadia and Owen, discussing a lecture on coral reefs and their seminar presentation. First, you have some time to look at Questions 21 to 24."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-24"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 24."},{"type":"sfx","note":"quiet café or corridor background, low"},{"type":"lines","from":0,"to":14},{"type":"announcer","text":"Before you hear the rest of the discussion, you have some time to look at Questions 25 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 25-30"},{"type":"announcer","text":"Now listen and answer Questions 25 to 30."},{"type":"lines","from":15,"to":33},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x01-l3-d","course":"ielts-exams","exam":"exam-01","unit":"x01-l3"},"exit":{"type":"exit","items":[{"tests":"paraphrase","point":1,"prompt":"In a recording, \"that wasn’t new for me\" usually means the speaker was...","options":["very surprised","confused","not surprised"],"correct":2,"why":{"en":"Something that is not new does not surprise you: this option is usually a distractor for \"surprised\".","tr":"Yeni olmayan bir şey seni şaşırtmaz: bu seçenek genelde \"şaşırdı\" sorusunda çeldiricidir.","fa":"چیزی که تازه نیست تعجبت را برنمی‌انگیزد: این گزینه معمولاً در سؤال «تعجب کرد» انحرافی است."}},{"tests":"word","point":3,"prompt":"A source \"full of statistics and specialist terms\" is best described as...","options":["too basic","too technical","out of date"],"correct":1,"why":{"en":"Specialist terms and statistics make a text technical.","tr":"Uzmanlık terimleri ve istatistikler metni teknik yapar.","fa":"اصطلاح‌های تخصصی و آمار، متن را تخصصی می‌کنند."}},{"tests":"method","point":2,"prompt":"One student suggests an idea, and the other says \"That would take ages to organise.\" What do you do?","options":["Do not choose it: it was rejected","Choose it: it was mentioned","Wait for the tutor"],"correct":0,"why":{"en":"A rejected suggestion is a typical distractor. Choose only what both accept.","tr":"Reddedilen bir öneri tipik bir çeldiricidir. Yalnızca ikisinin de kabul ettiğini seç.","fa":"پیشنهادِ ردشده گزینه‌ی انحرافیِ معمول است. فقط چیزی را انتخاب کن که هر دو قبول دارند."}},{"tests":"method","point":1,"prompt":"Questions 25-30 have a box of eight letters. How many letters will you use?","options":["eight","six, and one of them twice","six, each once"],"correct":2,"why":{"en":"\"Choose SIX answers from the box\": six letters, each once; two are left over.","tr":"\"Kutudan ALTI cevap seç\": altı harf, her biri bir kez; ikisi artar.","fa":"«شش جواب از کادر انتخاب کن»: شش حرف، هر کدام یک بار؛ دو تا اضافه می‌مانند."}},{"tests":"trap","point":3,"prompt":"\"It isn’t out of date, but it’s really just an introduction.\" Which opinion matches?","options":["It is out of date.","It is too basic.","It has the latest figures."],"correct":1,"why":{"en":"\"It isn’t out of date\" rules that option out; \"just an introduction\" = too basic.","tr":"\"Eski değil\" o seçeneği eler; \"sadece bir giriş\" = fazla temel.","fa":"«قدیمی نیست» آن گزینه را رد می‌کند؛ «فقط یک مقدمه» یعنی خیلی مقدماتی."}}],"id":"c-x01-l3-x","course":"ielts-exams","exam":"exam-01","unit":"x01-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
